export type MailJob = {
  /**
   * 任务 id
   */
  id: string;
  /**
   * 收件邮箱
   */
  to: string;
  /**
   * 关联的玩家账号 id；null = 未关联账号
   */
  accountId: string | null;
  /**
   * 关联的玩家账号名；账号已被删则为 null
   */
  accountName: string | null;
  /**
   * 模板 key
   */
  templateKey: string;
  /**
   * 模板中文名（模板已被删则退回 key）
   */
  templateName: string;
  /**
   * 渲染后的标题
   */
  subject: string;
  /**
   * 渲染后的正文（重投时发的仍是这份内容，模板改动不影响已入队的任务）
   */
  body: string;
  /**
   * 状态
   */
  status: "pending" | "sending" | "retrying" | "sent" | "failed";
  /**
   * 状态中文名
   */
  statusLabel: string;
  /**
   * 已尝试次数（成功的那次也计入）
   */
  attempts: number;
  /**
   * 下一次重试的时刻（毫秒）；待发送与终态为 null
   */
  nextRetryAt: number | null;
  /**
   * 最近一次失败的原因；成功为 null（界面可直接展示）
   */
  lastError: string | null;
  /**
   * 发起人管理员账号名（管理员被删后仍可追溯）
   */
  createdBy: string | null;
  /**
   * 入队时间（毫秒）
   */
  createdAt: number;
  /**
   * 最近更新时间（毫秒）
   */
  updatedAt: number;
  /**
   * 投递成功的时刻（毫秒）；未成功为 null
   */
  sentAt: number | null;
};

